using System.ComponentModel.DataAnnotations;

namespace BattleTanks.Domain.Entities;

public enum GameSessionStatus
{
    Waiting,
    InGame,
    Finished
}

public class GameSession
{
    public Guid Id { get; set; } = Guid.NewGuid();

    /// <summary>
    /// Short friendly code (e.g. TANK-4X9Z) generated by the Application layer.
    /// Players share this code with friends to join the room.
    /// </summary>
    [MaxLength(9)]
    public string RoomCode { get; set; } = string.Empty;

    /// <summary>
    /// Logical shard key (e.g. sa-east-1). Used for region-based routing/docs in LB-7.
    /// </summary>
    [MaxLength(32)]
    public string Region { get; set; } = "sa-east-1";

    [MaxLength(255)]
    public string MapSelected { get; set; } = string.Empty;

    public GameSessionStatus Status { get; set; } = GameSessionStatus.Waiting;

    // Navigation — players whose FK points to this session
    public ICollection<Player> ConnectedPlayers { get; set; } = new List<Player>();
}
